func TestEncodeAttrTypes(t *testing.T) {
	cases := []struct {
		name string
		in   any
		// check runs on the encoded value to assert the right
		// JSON type was used.
		check func(t *testing.T, v otlpAttrValue)
	}{
		{"string", "hello", func(t *testing.T, v otlpAttrValue) {
			if v.StringValue == nil || *v.StringValue != "hello" {
				t.Errorf("got %+v", v)
			}
		}},
		{"bool", true, func(t *testing.T, v otlpAttrValue) {
			if v.BoolValue == nil || !*v.BoolValue {
				t.Errorf("got %+v", v)
			}
		}},
		{"int", 7, func(t *testing.T, v otlpAttrValue) {
			if v.IntValue == nil || *v.IntValue != 7 {
				t.Errorf("got %+v", v)
			}
		}},
		{"float", 1.5, func(t *testing.T, v otlpAttrValue) {
			if v.DoubleValue == nil || *v.DoubleValue != 1.5 {
				t.Errorf("got %+v", v)
			}
		}},
		{"uint64_within_int63", uint64(1<<63 - 1), func(t *testing.T, v otlpAttrValue) {
			if v.IntValue == nil || *v.IntValue != 1<<63-1 {
				t.Errorf("got %+v, want IntValue=%d", v, int64(1<<63-1))
			}
		}},
		{"uint64_overflow", uint64(1 << 63), func(t *testing.T, v otlpAttrValue) {
			// Values > 1<<63-1 cannot fit in int64; must degrade
			// to DoubleValue so the OTLP body stays valid.
			if v.DoubleValue == nil || *v.DoubleValue != float64(1<<63) {
				t.Errorf("got %+v, want DoubleValue=%f", v, float64(1<<63))
			}
		}},
		{"float32", float32(1.5), func(t *testing.T, v otlpAttrValue) {
			if v.DoubleValue == nil || *v.DoubleValue != float64(float32(1.5)) {
				t.Errorf("got %+v, want DoubleValue", v)
			}
		}},
		{"unknown", struct{ X int }{X: 1}, func(t *testing.T, v otlpAttrValue) {
			if v.StringValue == nil || !strings.Contains(*v.StringValue, "{") {
				t.Errorf("expected struct fallback to string, got %+v", v)
			}
		}},
		{"unknown_empty_struct", struct{}{}, func(t *testing.T, v otlpAttrValue) {
			// Default branch must fmt.Sprintf the value into a
			// StringValue so the collector can still index it.
			want := fmt.Sprintf("%v", struct{}{})
			if v.StringValue == nil || *v.StringValue != want {
				t.Errorf("got %+v, want StringValue=%q", v, want)
			}
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			tc.check(t, encodeAttr(tc.in))
		})
	}
}

// Compile-time guard that Exporter satisfies any expected interface.
var _ io.Closer = (*Exporter)(nil)

func TestExporterPerCallTimeout(t *testing.T) {
	// A stalled collector must NOT block Close indefinitely — the
	// per-call context cancels the in-flight POST.
	block := make(chan struct{})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		<-block
	}))
	defer srv.Close()
	defer close(block)

	e := NewExporter(ExporterConfig{
		Endpoint: srv.URL,
		Timeout:  50 * time.Millisecond,
	})
	defer e.Close()
	_, s := e.StartSpan(Context{TraceID: NewTraceID()}, "op")
	s.End()

	// Close should return promptly (well under the 50ms per-call
	// timeout * 64-spans-in-batch — in practice one batch flush).
	done := make(chan error, 1)
	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		defer cancel()
		_ = ctx
		done <- e.Close()
	}()
	select {
	case err := <-done:
		if err != nil {
			t.Errorf("Close: %v", err)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Close blocked longer than 2s")
	}
}

func TestExporterQueueDepth(t *testing.T) {
	// Build a server that hangs forever so the export loop never
	// drains the buffer. Submit must drop, not block.
	release := make(chan struct{})
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		<-release
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()
	defer close(release)

	e := NewExporter(ExporterConfig{
		Endpoint:  srv.URL,
		QueueSize: 4,
	})
	defer e.Close()

	// QueueDepth should be 0 initially.
	if e.QueueDepth() != 0 {
		t.Errorf("initial QueueDepth() = %d, want 0", e.QueueDepth())
	}

	// Saturate the queue: the export goroutine reads items faster
	// than a tight submit loop can fill it, so we issue many spans
	// in parallel to force overflow on the contended buffer slot.
	// Use more submits than the original test to ensure contention
	// on the larger (4) queue.
	const total = 200
	var wg sync.WaitGroup
	wg.Add(total)
	for i := 0; i < total; i++ {
		go func() {
			defer wg.Done()
			_, s := e.StartSpan(Context{TraceID: NewTraceID()}, "overflow")
			s.End()
		}()
	}
	wg.Wait()

	// QueueDepth should be at most the queue size (4) since the
	// export goroutine may have drained some.
	if e.QueueDepth() > 4 {
		t.Errorf("QueueDepth() = %d, want <= 4", e.QueueDepth())
	}

	// Dropped count should be > 0 under contention.
	if e.Dropped() == 0 {
		t.Errorf("Dropped() = 0, want > 0 under contention (queue=4, %d submits)", total)
	}
}

func TestExporterNilRespNetworkError(t *testing.T) {
	// Issue #565: network-level errors (DNS failure, connection refused)
	// cause e.client.Do(req) to return (nil, err). The deferred
	// resp.Body.Close() must not panic when resp is nil.
	e := NewExporter(ExporterConfig{Endpoint: "http://127.0.0.1:1"})
	e.client.Transport = &errorTransport{err: context.DeadlineExceeded}
	defer e.Close()

	_, s := e.StartSpan(Context{TraceID: NewTraceID()}, "op")
	s.End()

	if err := e.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}
	if e.FlushFailures() == 0 {
		t.Error("FlushFailures() = 0, want > 0 after network error")
	}
}

func TestExporterRetryParamsConfigurable(t *testing.T) {
	// Issue #803: retry parameters must be configurable via ExporterConfig.
	// Verify the constructor applies custom values and falls back to
	// defaults when <= 0.
	var attempts atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		attempts.Add(1)
		w.WriteHeader(http.StatusServiceUnavailable)
	}))
	defer srv.Close()

	// Custom: 1 retry with 10ms base, 50ms max.
	e := NewExporter(ExporterConfig{
		Endpoint:       srv.URL,
		MaxRetries:     1,
		RetryBaseDelay: 10 * time.Millisecond,
		MaxRetryDelay:  50 * time.Millisecond,
	})
	if e == nil {
		t.Fatal("NewExporter returned nil")
	}
	defer e.Close()

	_, s := e.StartSpan(Context{TraceID: NewTraceID()}, "op")
	s.End()
	if err := e.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	// Initial attempt + 1 retry = 2 total attempts.
	if got := attempts.Load(); got != 2 {
		t.Errorf("attempts = %d, want 2 (initial + 1 retry)", got)
	}
	if e.FlushFailures() == 0 {
		t.Error("FlushFailures() = 0, want > 0 after retries exhausted")
	}
}

func TestExporterRetryParamsDefaults(t *testing.T) {
	// When MaxRetries/RetryBaseDelay/MaxRetryDelay are 0 (or negative),
	// the constructor must fall back to the defaults.
	var attempts atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		attempts.Add(1)
		w.WriteHeader(http.StatusServiceUnavailable)
	}))
	defer srv.Close()

	e := NewExporter(ExporterConfig{
		Endpoint:       srv.URL,
		MaxRetries:     0, // should fall back to defaultMaxRetries (3)
		RetryBaseDelay: 0,
		MaxRetryDelay:  0,
	})
	if e == nil {
		t.Fatal("NewExporter returned nil")
	}
	defer e.Close()

	_, s := e.StartSpan(Context{TraceID: NewTraceID()}, "op")
	s.End()
	if err := e.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	// Initial attempt + 3 retries = 4 total attempts.
	if got := attempts.Load(); got != 4 {
		t.Errorf("attempts = %d, want 4 (initial + 3 retries)", got)
	}
}

func TestExporterRetryParamsNegative(t *testing.T) {
	// Negative values must also fall back to defaults.
	var attempts atomic.Int32
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		attempts.Add(1)
		w.WriteHeader(http.StatusServiceUnavailable)
